SELECT WBS1, REPLACE(REPLACE(Name, NCHAR(8220), ''''), NCHAR(8221), '''') AS Name, REPLACE(REPLACE(LongName, NCHAR(8220), ''''), NCHAR(8221), '''') AS LongName,
       ClientID, REPLACE(REPLACE(Address1, NCHAR(8220), ''''), NCHAR(8221), '''') AS Address1, City, State, CreateDate, StartDate, ContractDate, Stage, ChargeType, Fee, ProjMgr, Principal, ProjectType, Status
FROM OPENQUERY([DELTEK_VP], 'SELECT RTRIM(WBS1) AS WBS1, Name, LongName, RTRIM(ClientID) AS ClientID, Address1, City, State, CONVERT(varchar(10), CreateDate, 23) AS CreateDate, CONVERT(varchar(10), StartDate, 23) AS StartDate, CONVERT(varchar(10), ContractDate, 23) AS ContractDate, Stage, ChargeType, Fee, RTRIM(ProjMgr) AS ProjMgr, RTRIM(Principal) AS Principal, ProjectType, Status FROM [C0000052267P_1_KOR00000000].dbo.PR WHERE LTRIM(RTRIM(ISNULL(WBS2, ''''))) = '''' AND LTRIM(RTRIM(ISNULL(WBS3, ''''))) = ''''') FOR JSON PATH
